steps.body:
`fetch` resolves to a `Response`. `res.ok` is `true` for a status from 200 to 299, `res.status` is the number, and `await res.json()` parses the body. But `res.json()` is typed `any`, so whatever the server sent flows into your code unchecked:

```typescript
const res = Response.json({ id: 7, name: "Ada" });
const body = await res.json();
//    ^? const body: any
console.log(res.ok, res.status); // true 200
console.log(body.nmae); // undefined
```

`Response.json(data)` builds a real response with a JSON body, which is how the fakes in this lesson answer. Store the body as `unknown` and validate it. Better still, do that in one helper that every request goes through: it checks the status, parses the body with the schema you pass, and returns that schema's output type. `z.ZodType` is the type every zod schema has, so `S extends z.ZodType` accepts any schema, and `z.output<S>` is what that schema parses to.

examples.code:
type User = { id: number; name: string; email: string };

// The API renamed email to mail, and nobody told this client.
const fakeFetch: typeof fetch = async () =>
  Response.json({ id: 7, name: "Ada Lovelace", mail: "ada@example.com" });

async function getUser(id: number): Promise<User> {
  const res = await fakeFetch(`https://api.example.com/users/${id}`);
  const body = await res.json();
  //    ^? const body: any
  return body;
}

const user = await getUser(7);
console.log(`Name: ${user.name}`);
console.log(`Email: ${user.email.toLowerCase()}`);

import * as z from "zod";

class HttpError extends Error {
  override readonly name = "HttpError";
  readonly status: number;
  constructor(status: number, url: string) {
    super(`${url} answered ${status}`);
    this.status = status;
  }
}

async function getJson<S extends z.ZodType>(
  url: string,
  schema: S,
  fetchFn: typeof fetch,
): Promise<z.output<S>> {
  const res = await fetchFn(url);
  if (!res.ok) {
    throw new HttpError(res.status, url);
  }
  const body: unknown = await res.json();
  return schema.parse(body);
}

const Product = z.object({ sku: z.string(), name: z.string(), priceCents: z.number().int() });

const products: Record<string, unknown> = {
  "/products/MUG-001": { sku: "MUG-001", name: "Mug", priceCents: 1250 },
  "/products/TEA-002": { sku: "TEA-002", name: "Tea", priceCents: "4.50" },
};
const fakeFetch: typeof fetch = async (input) => {
  const body = products[new URL(String(input)).pathname];
  return body === undefined
    ? Response.json({ error: "not found" }, { status: 404 })
    : Response.json(body);
};

for (const sku of ["MUG-001", "TEA-002", "PLT-404"]) {
  try {
    const product = await getJson(`https://api.example.com/products/${sku}`, Product, fakeFetch);
    //    ^? const product: { sku: string; name: string; priceCents: number; }
    console.log(`${sku}: ${product.name}, ${product.priceCents} cents`);
  } catch (err) {
    if (err instanceof HttpError) {
      console.log(`${sku}: HTTP ${err.status}`);
    } else if (err instanceof z.ZodError) {
      for (const issue of err.issues) {
        console.log(`${sku}: bad response: ${issue.path.join(".")}: ${issue.message}`);
      }
    } else {
      throw err;
    }
  }
}

import * as z from "zod";

async function getJson<S extends z.ZodType>(
  url: string,
  schema: S,
  fetchFn: typeof fetch = fetch,
): Promise<z.output<S>> {
  const res = await fetchFn(url);
  if (!res.ok) {
    throw new Error(`${url} answered ${res.status}`);
  }
  const body: unknown = await res.json();
  return schema.parse(body);
}

function fakeApi(routes: Record<string, unknown>) {
  const requests: string[] = [];
  const fetchFn: typeof fetch = async (input) => {
    const path = new URL(String(input)).pathname;
    requests.push(path);
    const body = routes[path];
    return body === undefined
      ? Response.json({ error: "not found" }, { status: 404 })
      : Response.json(body);
  };
  return { fetchFn, requests };
}

const Weather = z.object({ city: z.string(), tempC: z.number() });

const api = fakeApi({
  "/weather/oslo": { city: "Oslo", tempC: -3.5 },
  "/weather/lima": { city: "Lima", tempC: 19 },
});

for (const city of ["oslo", "lima"]) {
  const weather = await getJson(`https://api.example.com/weather/${city}`, Weather, api.fetchFn);
  console.log(`${weather.city}: ${weather.tempC}°C`);
}
console.log(`${api.requests.length} requests: ${api.requests.join(", ")}`);

