steps.body:
Throwing for every status that isn't a success makes each caller wrap each request in `try` and guess what failed. But a 404 or a 429 isn't a bug. It's an answer your code should handle, like the expected failures in the Results Instead of Exceptions lesson. So model the answers as a discriminated union:

```typescript types
type ApiResult<T> =
  | { kind: "ok"; data: T }
  | { kind: "not_found" }
  | { kind: "rate_limited"; retryAfterSeconds: number }
  | { kind: "server_error"; status: number };
```

Build it from `res.status` and the headers. `res.headers.get(name)` returns `string | null`, and header names ignore case:

```typescript
const res = new Response(null, { status: 429, headers: { "Retry-After": "30" } });
console.log(res.ok, res.status); // false 429
console.log(res.headers.get("retry-after")); // 30
```

Keep throwing for statuses that mean a bug in your own code, like a 400 for a request you built wrong. No caller can do anything useful with those.

examples.code:
import * as z from "zod";

type ApiResult<T> =
  | { kind: "ok"; data: T }
  | { kind: "not_found" }
  | { kind: "rate_limited"; retryAfterSeconds: number }
  | { kind: "server_error"; status: number };

function retryAfter(res: Response): number {
  const seconds = Number.parseInt(res.headers.get("Retry-After") ?? "", 10);
  return Number.isNaN(seconds) ? 60 : seconds;
}

async function toApiResult<S extends z.ZodType>(
  res: Response,
  schema: S,
): Promise<ApiResult<z.output<S>>> {
  if (res.ok) {
    const body: unknown = await res.json();
    return { kind: "ok", data: schema.parse(body) };
  }
  if (res.status === 404) return { kind: "not_found" };
  if (res.status === 429) return { kind: "rate_limited", retryAfterSeconds: retryAfter(res) };
  if (res.status >= 500) return { kind: "server_error", status: res.status };
  throw new Error(`unexpected status ${res.status}`);
}

const User = z.object({ id: z.number(), name: z.string() });

const responses = [
  Response.json({ id: 1, name: "Ada" }),
  Response.json({ error: { code: "not_found", message: "No user 2" } }, { status: 404 }),
  new Response(null, { status: 429, headers: { "Retry-After": "120" } }),
  new Response("Service Unavailable", { status: 503 }),
];

for (const res of responses) {
  const result = await toApiResult(res, User);
  //    ^? const result: ApiResult<{ id: number; name: string; }>
  console.log(JSON.stringify(result));
}

import * as z from "zod";

const ErrorEnvelope = z.object({
  error: z.object({ code: z.string(), message: z.string() }),
});

async function errorMessage(res: Response): Promise<string> {
  const body: unknown = await res.json().catch(() => null);
  const envelope = ErrorEnvelope.safeParse(body);
  if (envelope.success) {
    return `${envelope.data.error.code}: ${envelope.data.error.message}`;
  }
  return `HTTP ${res.status} with no error details`;
}

const responses = [
  Response.json({ error: { code: "user_not_found", message: "No user has id 42" } }, { status: 404 }),
  Response.json(
    { error: { code: "email_taken", message: "That email is already registered" } },
    { status: 409 },
  ),
  new Response("<html><h1>502 Bad Gateway</h1></html>", {
    status: 502,
    headers: { "Content-Type": "text/html" },
  }),
];

for (const res of responses) {
  console.log(`${res.status} ${await errorMessage(res)}`);
}

type User = { id: number; name: string };

type ApiResult<T> =
  | { kind: "ok"; data: T }
  | { kind: "not_found" }
  | { kind: "rate_limited"; retryAfterSeconds: number }
  | { kind: "server_error"; status: number };

function assertNever(value: never): never {
  throw new Error(`Unexpected value: ${JSON.stringify(value)}`);
}

function message(result: ApiResult<User>): string {
  switch (result.kind) {
    case "ok":
      return `Welcome back, ${result.data.name}!`;
    case "not_found":
      return "We couldn't find that account.";
    case "rate_limited":
      return `Too many requests. Try again in ${Math.ceil(result.retryAfterSeconds / 60)} min.`;
    case "server_error":
      return `Something went wrong on our side (${result.status}). Please try again.`;
    default:
      return assertNever(result);
  }
}

const results: ApiResult<User>[] = [
  { kind: "ok", data: { id: 1, name: "Ada" } },
  { kind: "not_found" },
  { kind: "rate_limited", retryAfterSeconds: 90 },
  { kind: "server_error", status: 503 },
];

for (const result of results) {
  console.log(message(result));
}

