steps.body:
List endpoints return a page at a time: some items, and a cursor that fetches the next page, or `null` on the last one. Every list endpoint wraps a different item in the same envelope, so write the envelope once, as a function that takes the item's schema:

```typescript
import * as z from "zod";

function pageOf<T extends z.ZodType>(item: T) {
  return z.object({ items: z.array(item), nextCursor: z.string().nullable() });
}

const TagPage = pageOf(z.string());
const page = TagPage.parse({ items: ["ts", "zod"], nextCursor: null });
console.log(page.items.join(", ")); // ts, zod
```

`T extends z.ZodType` accepts any schema, and the return type is inferred from the `z.object` the function builds, so it keeps the item schema you passed. To read every page, an async generator fetches one page, checks it, yields its items one at a time, and follows `nextCursor` until it's `null`. The caller just loops with `for await`, or collects everything with `Array.fromAsync`.

examples.code:
import * as z from "zod";

function pageOf<T extends z.ZodType>(item: T) {
  return z.object({
    items: z.array(item),
    nextCursor: z.string().nullable(),
  });
}

const Product = z.object({ sku: z.string(), name: z.string() });
const Order = z.object({ id: z.string(), totalCents: z.number().int() });

const ProductPage = pageOf(Product);
type ProductPage = z.infer<typeof ProductPage>;
//   ^? type ProductPage = { items: { sku: string; name: string; }[]; nextCursor: string | null; }
const OrderPage = pageOf(Order);
type OrderPage = z.infer<typeof OrderPage>;
//   ^? type OrderPage = { items: { id: string; totalCents: number; }[]; nextCursor: string | null; }

const products = ProductPage.parse({
  items: [
    { sku: "MUG-001", name: "Mug" },
    { sku: "TEA-002", name: "Tea" },
  ],
  nextCursor: "p2",
});
console.log(`${products.items.map((p) => p.name).join(", ")}, next: ${products.nextCursor}`);

const orders = OrderPage.parse({ items: [{ id: "ord_1", totalCents: 2500 }], nextCursor: null });
console.log(`${orders.items.length} order, last page: ${orders.nextCursor === null}`);

