    const body: unknown = await res.json();
    const result = ProductPage.safeParse(body);
    if (!result.success) {
      throw new Error(`page ${n} is invalid:\n${z.prettifyError(result.error)}`);
    }
    for (const product of result.data.items) {
      yield product;
    }
    const next = result.data.nextCursor;
    url = next === null ? null : `https://api.example.com/products?cursor=${next}`;
  }
}

