export const Customer = z.object({ id: z.string(), name: z.string().min(1) });
export type Customer = z.infer<typeof Customer>;

export function pageOf<T extends z.ZodType>(item: T) {
  return z.object({ items: z.array(item), nextCursor: z.string().nullable() });
}

const CustomerPage = pageOf(Customer);

export async function* allCustomers(fetchFn: typeof fetch): AsyncGenerator<Customer> {
  let url: string | null = "https://api.example.com/customers";
  while (url !== null) {
    const res = await fetchFn(url);
    if (!res.ok) {
      throw new Error(`${url} answered ${res.status}`);
    }
    const body: unknown = await res.json();
    const page = CustomerPage.parse(body);
    for (const customer of page.items) {
      yield customer;
    }
    const next = page.nextCursor;
    url = next === null ? null : `https://api.example.com/customers?cursor=${next}`;
  }
}

const pages: Record<string, unknown> = {
  first: {
    items: [{ id: "cus_01", name: "Ada Lovelace" }, { id: "cus_02", name: "Grace Hopper" }],
    nextCursor: "c2",
  },
  c2: {
    items: [{ id: "cus_03", name: "Alan Turing" }, { id: "cus_04", name: "Katherine Johnson" }],
    nextCursor: "c3",
  },
  c3: { items: [{ id: "cus_05", name: "Edsger Dijkstra" }], nextCursor: null },
};
const fakeFetch: typeof fetch = async (input) => {
  const body = pages[new URL(String(input)).searchParams.get("cursor") ?? "first"];
  return body === undefined
    ? Response.json({ error: "bad cursor" }, { status: 400 })
    : Response.json(body);
};

const customers = await Array.fromAsync(allCustomers(fakeFetch));
for (const customer of customers) {
  console.log(customer.name);
}
console.log(`${customers.length} customers`);
